package web

import (
	"io/fs"
	"log/slog"
	"net/http"
	"sort"
	"strings"

	"github.com/go-chi/chi/v5"
)

// apkDir is the directory inside the web FS the image build drops packaged TV
// client APKs into (the Dockerfile COPY android/apk/ → dist/assets/, slotted
// after the dist copy and before go build compiles the embed — design D3).
const apkDir = "dist/assets"

// The APK name law: mellifera-tv-<version>.apk. The filename is the entire
// version wire contract — no separate manifest is served.
const (
	apkNamePrefix = "mellifera-tv-"
	apkNameSuffix = ".apk"
)

// registerApk mounts the public /apk surface on the web mux (pattern-matched
// on registerSwagger): unauthenticated, registered ahead of the SPA fallback,
// and ALWAYS mounted — even when no APK is packaged. chi v5.3 does not fold
// HEAD into Get, so HEAD is an explicit mount or it 405s (the SPA probe is a
// HEAD request).
//
// The handler is a redirect, not a direct serve (design D2): 307 into the
// immutable /assets/* copy, with the Location written path-only — Go writes it
// verbatim, so a reverse-proxy scheme/host rewrite cannot corrupt it — and
// Cache-Control no-cache so the redirect itself is re-evaluated on every probe
// (the immutable cache law lives on the target, not the redirect).
func registerApk(r chi.Router, fsys fs.FS) {
	serve := func(w http.ResponseWriter, req *http.Request) {
		name, err := apkTarget(fsys)
		if err != nil {
			// Absent APK (bare checkout, CI image) is a supported steady
			// state: 404, never the SPA index fallback.
			http.NotFound(w, req)
			return
		}
		w.Header().Set("Cache-Control", "no-cache")
		http.Redirect(w, req, "/assets/"+name, http.StatusTemporaryRedirect)
	}
	r.Get("/apk", serve)
	r.Head("/apk", serve)
}

// apkTarget returns the packaged APK filename to redirect to: the lexically
// first mellifera-tv-*.apk under apkDir. An absent APK is fs.ErrNotExist.
//
// More than one match logs a WARN and serves the lexically-first. With the
// embedded dist the content is fixed at boot, so the WARN is a boot WARN; the
// no-clobber release contract (one filename ↔ one bytes) makes >1 a packaging
// defect, not a choice the route may flip-flop on between requests.
func apkTarget(fsys fs.FS) (string, error) {
	entries, err := fs.ReadDir(fsys, apkDir)
	if err != nil {
		return "", err
	}
	var matches []string
	for _, e := range entries {
		name := e.Name()
		if !e.IsDir() && strings.HasPrefix(name, apkNamePrefix) && strings.HasSuffix(name, apkNameSuffix) {
			matches = append(matches, name)
		}
	}
	if len(matches) == 0 {
		return "", fs.ErrNotExist
	}
	sort.Strings(matches)
	if len(matches) > 1 {
		slog.Warn("web: multiple packaged TV APKs, serving lexically-first",
			"dir", apkDir, "serving", matches[0], "count", len(matches))
	}
	return matches[0], nil
}

// apkFS returns the FS apk discovery reads. The zero Options is the production
// configuration: the embedded dist tree; tests inject a synthetic FS instead.
func (o Options) apkFS() fs.FS {
	if o.ApkFS != nil {
		return o.ApkFS
	}
	return distFS
}
